using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using MegaCrit.Sts2.Core.CardSelection;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using MegaCrit.Sts2.Core.Localization.DynamicVars;

namespace MegaCrit.Sts2.Core.Models.Cards;

public sealed class Dredge : CardModel
{
	protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new CardsVar(3));

	public override IEnumerable<CardKeyword> CanonicalKeywords => new global::<>z__ReadOnlySingleElementList<CardKeyword>(CardKeyword.Exhaust);

	public Dredge()
		: base(1, CardType.Skill, CardRarity.Uncommon, TargetType.Self)
	{
	}

	protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
	{
		await CreatureCmd.TriggerAnim(base.Owner.Creature, "Cast", base.Owner.Character.CastAnimDelay);
		int num = Math.Min(base.DynamicVars.Cards.IntValue, CardPile.MaxCardsInHand - PileType.Hand.GetPile(base.Owner).Cards.Count);
		if (num > 0)
		{
			await CardPileCmd.Add(await CardSelectCmd.FromCombatPile(choiceContext, PileType.Discard.GetPile(base.Owner), base.Owner, new CardSelectorPrefs(base.SelectionScreenPrompt, num)), PileType.Hand);
		}
	}

	protected override void OnUpgrade()
	{
		AddKeyword(CardKeyword.Retain);
	}
}

TaskTaintedContinuation.cs.source:
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Afflictions;
using MegaCrit.Sts2.Core.Models.Enchantments;
using MegaCrit.Sts2.Core.Models.Powers;
using MegaCrit.Sts2.Core.Nodes;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private async Task RunTaintedContinuationContractAsync(CombatState live, Player player)
    {
        foreach (var relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        foreach (var potion in player.PotionSlots.ToArray()) potion?.Discard();
        var enemy = live.Enemies.Single();
        await CreatureCmd.SetCurrentHp(enemy, 1000);
        await PowerCmd.Apply<VitalSparkPower>(new BlockingPlayerChoiceContext(), enemy, 3, null, null);
        foreach (string id in new[] { "DREDGE", "HOLOGRAM", "ACROBATICS" })
        foreach (int upgrade in new[] { 0, 1 })
        {
            foreach (var power in player.Creature.Powers.ToArray()) await PowerCmd.Remove(power);
            await ClearPlayerPilesAsync(player);
            await InjectCardAsync(live, player, new()
            {
                CardId = id, UpgradeLevels = upgrade, Pile = "Hand",
                AfflictionId = "TAINTED", AfflictionAmount = upgrade == 0 ? 3 : 4,
            });
            foreach (string other in new[] { "DEFEND_SILENT", "STRIKE_SILENT", "BACKFLIP" })
                await InjectCardAsync(live, player, new() { CardId = other, Pile = "Hand" });
            foreach (string other in new[] { "STRIKE_DEFECT", "DEFEND_DEFECT", "DEADLY_POISON", "FLASH_OF_STEEL", "STRIKE_IRONCLAD", "BASH" })
                await InjectCardAsync(live, player, new() { CardId = other, Pile = "Draw" });
            foreach (string other in new[] { "STRIKE_NECROBINDER", "DEFEND_NECROBINDER", "STRIKE_REGENT", "DEFEND_REGENT", "STRIKE_IRONCLAD", "DEFEND_IRONCLAD" })
                await InjectCardAsync(live, player, new() { CardId = other, Pile = "Discard" });
            SetEnergy(player, 10);
            CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
            SolverDisplayNames names = SolverDisplayNames.Capture(live);
            var parent = root.ForkSimulator();
            PredictedCard Card(CombatPredictionSimulator sim) => sim.State.GetPlayerCombatState(player)
                .Hand.Cards.Single(card => card.Preview.Id.Entry == id);
            string Stamp(CombatPredictionSimulator sim) => DescribeContinuationContractState(sim, root, player);
            void Equal(string expected, string actual, string label)
            {
                if (expected != actual) throw new InvalidOperationException($"{id}+{upgrade} {label}:\nEXPECTED\n{expected}\nACTUAL\n{actual}");
            }
            void Finish(CombatPredictionSimulator sim, ForkableSet<uint> deaths)
            {
                var combat = (SimulatedCombatState)sim.State.CombatState;
                if (!CorePowerSupport.ApplyEnemyDeathPowers(sim, combat, combat.KnownEnemies, deaths)
                    || !CombatBeamSolver.SettleReplayActionBoundary(sim, combat))
                    throw new InvalidOperationException("Unexpected post-action choice.");
                sim.CheckWinCondition(root.StartTurnNumber);
            }
            CombatPredictionSimulator Legacy(IReadOnlyList<PlanCardChoice>? choices)
            {
                using var isolation = SimulationNotificationIsolation.Enter();
                var sim = parent.Fork(); var combat = (SimulatedCombatState)sim.State.CombatState;
                ForkableSet<uint> deaths = [];
                combat.BeginActionChoices(choices);
                try
                {
                    using (combat.BeginCardExecutionScope(deaths))
                        if (sim.ManualPlay(Card(sim), null, out _)) Finish(sim, deaths);
                }
                finally { combat.EndActionChoices(); }
                return sim;
            }
            if (Card(parent).Preview.Affliction is not Tainted
                || !CombatPredictionSimulator.SupportsManualCardChoiceContinuation(Card(parent).Preview))
                throw new InvalidOperationException("Expected audited Tainted eligibility.");
            string parentBefore = Stamp(parent), liveBefore = ContinuationStamp.CaptureLive(live).StateText;
            var discovery = Legacy(null);
            var request = ((SimulatedCombatState)discovery.State.CombatState).PendingTurnStartChoice
                ?? throw new InvalidOperationException("No own selection.");
            var choices = CardChoiceSupport.BuildChoices(request.Spec!, names, 256, 256).ToArray();
            if (choices.Length < 6) throw new InvalidOperationException("Too few selection alternatives.");
            string[] references = choices.Select(choice => Stamp(Legacy([choice]))).ToArray();
            CardContinuationContractCheckpoint? captured;
            using (SimulationNotificationIsolation.Enter())
            {
                var seed = parent.Fork();
                captured = CaptureCardContinuationContract(seed, Card(seed), null, []);
            }
            using var checkpoint = captured ?? throw new InvalidOperationException("Tainted selector frame not captured.");
            CombatPredictionSimulator Resume(int index)
            {
                using var isolation = SimulationNotificationIsolation.Enter();
                var child = checkpoint.Resume([choices[index]], CancellationToken.None);
                if (!child.Completed) throw new InvalidOperationException("Selector tail unexpectedly incomplete.");
                Finish(child.Simulator, child.Deaths);
                if (((SimulatedCombatState)child.Simulator.State.CombatState).GetAmount<TaintedPower>(player.Creature) != 3)
                    throw new InvalidOperationException("VitalSpark tail was missing or duplicated.");
                return child.Simulator;
            }
            for (int i = choices.Length - 1; i >= 0; i--)
            {
                var resumed = Resume(i);
                Equal(references[i], Stamp(resumed), "all choices " + i);
                var starts = resumed.History.OfType<CombatPredictionCardPlayStartedEntry>().ToArray();
                var ends = resumed.History.OfType<CombatPredictionCardPlayFinishedEntry>().ToArray();
                var playedCard = resumed.State.GetPlayerCombatState(player).AllCards.Single(card => card.Preview.Id.Entry == id);
                if (starts.Length != 1 || ends.Length != 1
                    || !ReferenceEquals(starts[0].CardPlay, ends[0].CardPlay)
                    || !ReferenceEquals(starts[0].Trace, ends[0].Trace)
                    || !ReferenceEquals(starts[0].CardPlay.Card, playedCard.Preview))
                    throw new InvalidOperationException("Active play/trace/card identity lost.");
                foreach (var draw in resumed.History.OfType<CombatPredictionCardDrawnEntry>())
                    if (!ReferenceEquals(resumed.History.GetResolvedEntry<CombatPredictionCardDrawResolvedEntry>(draw).OriginalEntry, draw))
                        throw new InvalidOperationException("Deferred draw pairing lost.");
                Equal(Stamp(resumed), Stamp(resumed.Fork()), "completed Fork");
            }
            var first = Resume(0); string firstBefore = Stamp(first);
            _ = Resume(choices.Length - 1);
            Equal(firstBefore, Stamp(first), "sibling isolation");
            using (SimulationNotificationIsolation.Enter())
            {
                var played = first.State.GetPlayerCombatState(player).AllCards.Single(card => card.Preview.Id.Entry == id);
                played.MutablePreview.Affliction!.Amount += 7;
            }
            Equal(references[0], Stamp(Resume(0)), "affliction mutation isolation");
            string[] parallel = await Task.WhenAll(Enumerable.Range(0, 16)
                .Select(i => Task.Run(() => Stamp(Resume(i % choices.Length)))));
            for (int i = 0; i < parallel.Length; i++) Equal(references[i % choices.Length], parallel[i], "DOP16");
            using (SimulationNotificationIsolation.Enter())
            {
                var unknown = parent.Fork(); var card = Card(unknown);
                card.ClearAffliction(); unknown.Afflict<Bound>(card, 1);
                if (CombatPredictionSimulator.SupportsManualCardChoiceContinuation(card.Preview))
                    throw new InvalidOperationException("Unaudited affliction admitted.");
                var enchanted = parent.Fork(); Card(enchanted).Enchant(ModelDb.Enchantment<Swift>().ToMutable(), 1m);
                if (CombatPredictionSimulator.SupportsManualCardChoiceContinuation(Card(enchanted).Preview))
                    throw new InvalidOperationException("Enchantment admitted.");
            }
            Equal(parentBefore, Stamp(parent), "parent state history RNG");
            Equal(liveBefore, ContinuationStamp.CaptureLive(live).StateText, "live isolation");
            var expected = Legacy([choices[0]]);
            string expectedNative = ContinuationStamp.CapturePredicted(player, expected, root.StartTurnNumber,
                root.Forecast, root.StartTurnNumber).StateText;
            CardModel nativeCard = player.PlayerCombatState!.Hand.Cards.Single(card => card.Id.Entry == id);
            using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(15));
            using var session = NativeChoiceRuntime.Begin(live, player, "test:tainted-continuation");
            session.SetPlanAndStartDriving(NGame.Instance!, [choices[0] with { SourceId = id }], deadline.Token);
            GameAction action = await SolverController.EnqueueAndCaptureActionAsync(
                queued => queued is PlayCardAction played && ReferenceEquals(played.NetCombatCard.ToCardModelOrNull(), nativeCard),
                () => { if (!nativeCard.TryManualPlay(null)) throw new InvalidOperationException("Native card unplayable."); }, deadline.Token);
            await session.AwaitProducerAndCompleteAsync(action.CompletionTask).WaitAsync(deadline.Token);
            Equal(expectedNative, ContinuationStamp.CaptureLive(live).StateText, "native full state and RNG");
            Equal(parentBefore, Stamp(parent), "parent after native advance");
            Equal(references[0], Stamp(Resume(0)), "old checkpoint after native advance");
            _completedChecks.Add($"TaintedContinuation:{id}+{upgrade}:choices={choices.Length}:AllStateHistoryRng:VitalSparkOnce:AfflictionClone:Isolation:UnknownAttachmentRefusal:DOP16:NativeFullState:OldRootAfterLiveAdvance");
        }
    }
}

